  @Test
  void secretValue() {
    SecretValue v = SecretValue.of("text", "3");
    assertThat(v.toString()).isEqualTo("SecretValue([REDACTED])");
    assertThat(Json.stringify(List.of(v))).isEqualTo("[\"[REDACTED]\"]");
    assertThat(v.version()).contains("3");
    assertThat(v.revealBytes()).isEqualTo("text".getBytes());
    assertThat(v.sha256()).hasSize(64);
    assertThat(v.sameAs(SecretValue.of("text", "3"))).isTrue();
    assertThat(v.sameAs(SecretValue.of("text"))).isFalse();
    assertThat(v.sameAs(SecretValue.of("other", "3"))).isFalse();
    assertThat(v.sameAs(null)).isFalse();
    SecretValue binary = SecretValue.ofBytes(new byte[] {(byte) 0xff, (byte) 0xfe}, null);
    assertThatThrownBy(binary::reveal).isInstanceOf(ValidationException.class);
    assertThat(SecretValue.of("{\"a\":[1]}").jsonNode().get("a").get(0).asInt()).isEqualTo(1);
    assertThat(SecretValue.of("[1,2]").json(new TypeReference<List<Integer>>() {}))
        .containsExactly(1, 2);
    assertThatThrownBy(() -> SecretValue.of("x").json(new TypeReference<List<Integer>>() {}))
        .isInstanceOf(ValidationException.class);
    v.clear();
    assertThat(v.revealBytes()).containsOnly(0);
  }

  @Test
  void secretMetadata() {
    SecretMetadata m =
        SecretMetadata.builder("n")
            .path("p/")
            .version("1")
            .createdAt(Instant.EPOCH)
            .updatedAt(Instant.EPOCH)
            .tags(Map.of("a", "b"))
            .versions(1)
            .extra("x", "y")
            .build();
    SecretMetadata copy = m.toBuilder().build();
    assertThat(copy).isEqualTo(m).hasSameHashCodeAs(m);
    assertThat(m).isNotEqualTo("n");
    assertThat(m).isNotEqualTo(SecretMetadata.builder("n").build());
    assertThat(m).isNotEqualTo(SecretMetadata.builder("other").build());
    assertThat(m.toString()).contains("name=n");
    assertThat(Json.stringify(m))
        .contains("\"name\":\"n\"")
        .contains("\"createdAt\":\"1970-01-01T00:00:00Z\"");
    assertThat(Json.stringify(SecretMetadata.builder("z").build()))
        .isEqualTo("{\"name\":\"z\",\"tags\":{},\"extra\":{}}");
    assertThat(SecretMetadata.builder("z").build().versions()).isEmpty();
  }

