  @Test
  void watchReportsChangesDeletionAndErrors() throws Exception {
    List<String> events = new java.util.concurrent.CopyOnWriteArrayList<>();
    List<Throwable> errors = new java.util.concurrent.CopyOnWriteArrayList<>();
    p.set("w", "1");
    WatchHandle h =
        p.watch(
            "w",
            Duration.ofMillis(20),
            (nv, ov) -> {
              events.add(
                  nv.map(SecretValue::reveal).orElse("null")
                      + "<-"
                      + ov.map(SecretValue::reveal).orElse("null"));
              if (nv.isPresent() && nv.get().reveal().equals("3")) {
                throw new IllegalStateException("listener failure");
              }
            },
            WatchOptions.builder()
                .onError(
                    e -> {
                      errors.add(e);
                      throw new IllegalStateException("onError failure is ignored");
                    })
                .build());
    Thread.sleep(100);
    p.set("w", "2");
    awaitSize(events, 1);
    p.failNext(new UnavailableException("blip"));
    awaitSize(errors, 1);
    p.set("w", "3");
    awaitSize(events, 2);
    awaitSize(errors, 2);
    p.delete("w");
    awaitSize(events, 3);
    assertThat(events).containsExactly("2<-1", "3<-2", "null<-3");
    h.stop();
    h.close();
    assertThat(h.isStopped()).isTrue();
  }

  @Test
  void watchUnversionedUsesHash() throws Exception {
    Map<String, Optional<SecretValue>> state =
        new HashMap<>(Map.of("v", Optional.of(SecretValue.of("a"))));
    try (Watcher w = new Watcher()) {
      List<String> events = new java.util.concurrent.CopyOnWriteArrayList<>();
      w.watch(
          () -> state.get("v"),
          Duration.ofMillis(10),
          (n, o) -> events.add(n.get().reveal()),
          WatchOptions.none());
      Thread.sleep(50);
      state.put("v", Optional.of(SecretValue.of("b")));
      awaitSize(events, 1);
      assertThat(events).containsExactly("b");
      assertThat(w.active()).isEqualTo(1);
      assertThatThrownBy(
              () -> w.watch(Optional::empty, Duration.ZERO, (n, o) -> {}, WatchOptions.none()))
          .isInstanceOf(IllegalArgumentException.class);
      assertThatThrownBy(
              () ->
                  w.watch(
                      Optional::empty, Duration.ofMillis(-1), (n, o) -> {}, WatchOptions.none()))
          .isInstanceOf(IllegalArgumentException.class);
    }
    Watcher closed = new Watcher();
    closed.close();
    assertThatThrownBy(
            () ->
                closed.watch(
                    Optional::empty, Duration.ofSeconds(1), (n, o) -> {}, WatchOptions.none()))
        .isInstanceOf(CancelledException.class)
        .hasMessageContaining("client is closed");
  }

